import{_ as e,o as a,c as n,a5 as r}from"./chunks/framework.BZzouRtU.js";const s="/study/images/game/input-actions-and-devices.svg",h=JSON.parse('{"title":"入力の基本 — デバイスからゲームのアクションへ","description":"","frontmatter":{"title":"入力の基本 — デバイスからゲームのアクションへ","study":{"source":"新規執筆","section":"reference","format":"article","status":"published","domain":"game","summary":"キーボードとゲームパッドから移動や攻撃を受け取る流れを、デバイス、コントロール、バインディング、アクション、更新時刻に分けて説明する。","aliases":["入力","input","デバイス","コントロール","バインディング","アクション","Action Map","押下","押し始め","ポーリング","デッドゾーン","リマップ","Input System"],"verification":"Unity Input System 1.11のActions・Bindings・Processors・Update Mode・UI入力の公式資料に照合（2026-11-07）"}},"headers":[],"relativePath":"game/basics/input-actions-and-devices.md","filePath":"game/basics/input-actions-and-devices.md"}'),o={name:"game/basics/input-actions-and-devices.md"};function i(d,t,c,m,u,p){return a(),n("div",null,[...t[0]||(t[0]=[r('<h1 id="入力の基本-—-デバイスからゲームのアクションへ" tabindex="-1">入力の基本 — デバイスからゲームのアクションへ <a class="header-anchor" href="#入力の基本-—-デバイスからゲームのアクションへ" aria-label="Permalink to &quot;入力の基本 — デバイスからゲームのアクションへ&quot;">​</a></h1><p>キーボードのキーとゲームパッドのスティックは、形も出す値も違います。ゲーム側では、どちらの入力も「移動する」という同じ操作に対応付けられます。機器から受け取る値とゲーム内の操作の対応を、主に<strong>Unity Input System 1.11</strong>の用語で説明します。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Actions.html" target="_blank" rel="noreferrer">Input Systemのアクション</a></p><h2 id="機器、操作箇所、ゲームの意味" tabindex="-1">機器、操作箇所、ゲームの意味 <a class="header-anchor" href="#機器、操作箇所、ゲームの意味" aria-label="Permalink to &quot;機器、操作箇所、ゲームの意味&quot;">​</a></h2><table tabindex="0"><thead><tr><th>用語</th><th>表すもの</th><th>例</th></tr></thead><tbody><tr><td><strong>デバイス</strong></td><td>入力を送る機器。</td><td>キーボード、マウス、ゲームパッド。</td></tr><tr><td><strong>コントロール</strong></td><td>デバイス上の操作箇所や状態。</td><td>Wキー、左スティック、マウス位置。</td></tr><tr><td><strong>バインディング</strong></td><td>コントロールとアクションの対応。</td><td>WASDや左スティックを移動へ対応付ける。</td></tr><tr><td><strong>アクション</strong></td><td>ゲームが使う操作の意味。</td><td>移動、攻撃、決定、キャンセル。</td></tr></tbody></table><p>例えば移動を二つの数値<code>(x, y)</code>で表せば、左右と前後の入力をまとめられます。キーボードの複数キーを合成した値や、スティックの値を移動アクションから読み、ゲームが速度や移動可能な状態と組み合わせて使います。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/ActionBindings.html" target="_blank" rel="noreferrer">Input Systemのバインディングと合成入力</a></p><figure class="study-figure"><img src="'+s+'" alt="WASDキーと左スティックを、それぞれのバインディングからMoveアクションへ対応付け、ゲームが移動に使う。ボタンは押されている状態と、押し始め・離した変化を区別する。" width="760" height="470" loading="lazy"><figcaption>上は異なる機器を同じ操作へ結び付ける流れ、下はボタンの状態と変化の例です。<a href="/study/images/game/input-actions-and-devices.svg" target="_blank" rel="noopener noreferrer">入力の対応と押下状態の図を拡大</a></figcaption></figure><h2 id="押されている状態と、変わった瞬間" tabindex="-1">押されている状態と、変わった瞬間 <a class="header-anchor" href="#押されている状態と、変わった瞬間" aria-label="Permalink to &quot;押されている状態と、変わった瞬間&quot;">​</a></h2><p>移動では「いま押されているか」、一回だけの攻撃では「この更新で押し始めたか」を使うなど、欲しい情報を選びます。アナログボタンでは、値がしきい値を越えたかなどの規則で押下を扱います。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/api/UnityEngine.InputSystem.InputAction.html" target="_blank" rel="noreferrer">InputActionの押下状態と変化</a></p><table tabindex="0"><thead><tr><th>調べるもの</th><th>使い方の例</th></tr></thead><tbody><tr><td><strong>現在の値</strong></td><td>スティックの向きと倒した量を読む。</td></tr><tr><td><strong>押されている</strong></td><td>キーを押している間、移動する。</td></tr><tr><td><strong>押し始めた</strong></td><td>押下へ変わった更新で、一回の攻撃を要求する。</td></tr><tr><td><strong>離した</strong></td><td>押下から戻った更新で、チャージなどの終了を要求する。</td></tr></tbody></table><p>長押し、短押しなどを区別する場合は、その判定の規則も定めます。Input Systemのアクションの<code>performed</code>などの通知は、アクションの種類やInteractionの設定によって起きる条件が変わります。欲しい操作に合う通知や状態を選びます。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Interactions.html" target="_blank" rel="noreferrer">Input SystemのInteraction</a></p><h2 id="小さな揺れと、操作の割り当てを扱う" tabindex="-1">小さな揺れと、操作の割り当てを扱う <a class="header-anchor" href="#小さな揺れと、操作の割り当てを扱う" aria-label="Permalink to &quot;小さな揺れと、操作の割り当てを扱う&quot;">​</a></h2><p>スティックは、中央に戻しても値が少しずれることがあります。<strong>デッドゾーン</strong>は、小さな入力をゼロとして扱うなどの範囲です。Input SystemのStick Deadzoneでは、大きさが最小値より小さい入力をゼロにし、範囲内の値を調整します。採用する処理によって、操作し始める感覚も変わります。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Processors.html#stick-deadzone" target="_blank" rel="noreferrer">Input Systemのデッドゾーン</a></p><p><strong>リマップ・リバインド</strong>は、操作の割り当てを変更することです。ゲームの「攻撃」という意味を保ちながら、別のキーやボタンへ対応を変えられます。変更を次回にも使う場合は、バインディングの上書き情報を保存し、起動時に適用する仕組みも用意します。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/ActionBindings.html#interactive-rebinding" target="_blank" rel="noreferrer">Input Systemの実行時リバインド</a></p><h2 id="いつ取得し、いつゲームへ適用するか" tabindex="-1">いつ取得し、いつゲームへ適用するか <a class="header-anchor" href="#いつ取得し、いつゲームへ適用するか" aria-label="Permalink to &quot;いつ取得し、いつゲームへ適用するか&quot;">​</a></h2><p><strong>ポーリング</strong>は、必要な時点で現在の値や状態を読む方式です。<strong>イベント・コールバック</strong>では、変化やアクションの通知を受け取る処理を登録します。いずれも、入力システムが機器の情報を処理する更新時刻と、ゲームが値を使う時刻を確認します。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/api/UnityEngine.InputSystem.InputAction.html" target="_blank" rel="noreferrer">InputActionのポーリングとコールバック</a></p><p>Unity Input Systemでは、入力イベントを描画フレームに対応した動的更新、固定更新、手動更新で処理する設定があります。固定更新が一フレームに複数回あれば、発射要求をどの更新で消費するかを決めます。また、短い間に押して離した操作を必要な回数だけ扱うには、現在の値に加えて変化や記録する情報も検討します。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Settings.html#update-mode" target="_blank" rel="noreferrer">Input Systemの更新設定</a> · <a href="/study/game/basics/game-loop-and-time.html">ゲームループと時間</a></p><h2 id="プレイ中とメニューで使う操作を切り替える" tabindex="-1">プレイ中とメニューで使う操作を切り替える <a class="header-anchor" href="#プレイ中とメニューで使う操作を切り替える" aria-label="Permalink to &quot;プレイ中とメニューで使う操作を切り替える&quot;">​</a></h2><p>同じ方向キーでも、プレイ中は移動、メニューでは選択先の変更へ使えます。Input Systemの<strong>Action Map</strong>は、関連するアクションをまとめて有効・無効にする単位です。プレイ用とUI用の入力をどの状態で使うか決めると、メニューを操作したときにキャラクターも動くといった干渉を扱えます。<a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/Actions.html" target="_blank" rel="noreferrer">Input Systemのアクションとマップ</a> · <a href="https://docs.unity3d.com/Packages/com.unity.inputsystem@1.11/manual/UISupport.html" target="_blank" rel="noreferrer">UI用の入力</a></p><p>画面側の選択や決定は<a href="/study/game/basics/ui-layout-and-interaction.html">ゲームUI</a>、ポーズ時の切り替えは<a href="/study/game/basics/game-states-and-pause.html">ゲームの状態とポーズ</a>、ゲーム内で決まった結果の通知は<a href="/study/game/basics/game-events-and-notifications.html">ゲーム内イベント</a>へ進みます。</p>',19)])])}const g=e(o,[["render",i]]);export{h as __pageData,g as default};
